\label{lem:candidate-first}
Within a complete-scanner query, no resource type can be registered
twice before a candidate type has been exposed twice.

\label{prop:cavity-equations}
For every directed incidence $A\to v$,
\begin{equation}\label{eq:cavity-branch-derivative}
 f'_{A\to v}(x)
 =-
 \prod_{u\in A\setminus\{v\}}q_{u\to A}(x).
\end{equation}
Consequently, defining $H_A(x):=\prod_{u\in A}q_{u\to A}(x)$,
we obtain
\begin{equation}\label{eq:cavity-root-derivative}
 q'_v(x)=-\sum_{A\ni v}H_A(x).
\end{equation}

\label{thm:cavity-stability}
Fix $r\ge3$, $q>2$, and $C,L,K<\infty$.
Let $\Gamma=\Gamma_n$ be simple $r$-uniform hypergraphs with
$N\le D^K$, $D\to\infty$ and $\delta=o(1)$.  Suppose
\[
 \left\|e^{-(r-1)t\mathsf T}\right\|_{L^q(\pi)\to L^q(\pi)}
 \le C(1+t)^L\qquad(0\le t\le T_D),
\]
\begin{equation}\label{eq:bootstrap-assumption}
 N^{1/q}\left(\delta+\frac{\log D}{D}\right)
 (1+\log D)^{2L+2}=o(1).
\end{equation}
Then, uniformly over $v,A\ni v$ and $0\le x\le1$,
\begin{align}
 q_v(x)&=(1+o(1))Q_D(x),\label{eq:cover-survival-asymptotic}\\
 f_{A\to v}(x)&=1-O_r\!\left(\frac{\log D}{D}\right).
 \label{eq:message-near-one}
\end{align}

\label{lem:log-equation}
For $x<1$,
\begin{equation}\label{eq:log-derivative}
 \frac{dy_v}{d\tau}
 =1-\frac1D
 \sum_{A\ni v}
 \exp\!\left(\sum_{u\in A\setminus\{v\}}y_u\right)
 \prod_{u\in A}f_{A\to u}^{-1}.
\end{equation}

\label{lem:message-estimate}
There is $h_0=h_0(r)>0$ such that the following holds.  
Suppose that $\max_v|y_v(x)|\le h_0$ on an interval $0\le x\le x_0$.
Then, for $D$ sufficiently large,
\begin{equation}\label{eq:message-correction}
 1-f_{A\to v}(x)
 \le C_r\frac{\log D}{D}
\end{equation}
uniformly over all directed incidences and all $0\le x\le x_0$.  In
particular,
\(
 f_{A\to v}(x)\ge\frac34.
\)

\label{lem:linearized}
On any interval $0\le\tau\le\tau_0<T_D$ on which
$\sup_{s\le\tau_0}\|y(s)\|_\infty\le h_0$, for every $q\ge1$,
\begin{equation}\label{eq:residual-bound}
 \left\|\frac{dy}{d\tau}+(r-1)\mathsf Ty\right\|_{L^q(\pi)}
 \le C_r\left[
 \delta+\frac{\log D}{D}
 +\|y\|_\infty\|y\|_{L^q(\pi)}
 \right].
\end{equation}

\label{thm:transfer}
For each fixed $r\ge3$ there are constants $C_r<\infty$ and
positive integers $\alpha_r,\gamma_r$ such that for every
$\kappa\ge2$, with $R=4\kappa+8$ and
$\bar q=N^{-1}\sum_vq_v(1)$, the number $Z$ of uncovered resources
satisfies
\begin{align}
 \left|\mathbb E(Z/N)-\bar q\right|
 &\le C_rR_0^{\alpha_r}(\chi_R+B^{-\kappa}),\label{eq:collision-moment-first}\\
 \left|\mathbb E[(Z/N)^2]-\bar q^2\right|
 &\le 2C_rR_0^{\alpha_r}(\chi_R+B^{-\kappa})
     +\frac{C_rR_0^{\gamma_r}}M.\label{eq:collision-moment-second}
\end{align}

\label{lem:one-label-exposure}
There are constants $C_r,H_r$ depending only on $r$ such that
$p_A\le C_rR_0^{H_r}/N$ for every candidate type $A$.

\label{cor:near-regular-handoff}
On $\mathcal G_\star$,
\begin{equation}\label{eq:resource-degrees}
 d_e=(1+n^{-\Omega_{F,\eta}(1)})D_\star
\end{equation}
uniformly in $e\in E(H_\star)$.  Consequently
$M=(1+o(1))ND_\star/r$ and $D_\star=n^{b\eta+o(1)}$.

\label{thm:resource-semigroup}
For every fixed $2<q<\infty$, on $\mathcal G_\star$,
\begin{equation}\label{eq:resource-semigroup-goal}
 \|e^{-(r-1)t\mathsf T}\|_{L^q(\pi_k)\to L^q(\pi_k)}
 \le C_{F,\eta,q}(1+t)^{s+1}
\end{equation}
whenever $0\le t\le(r-1)^{-1}\log(1+(r-1)D_\star)$.

By \eqref{eq:uniform-shadow-law}, conditional resampling on the
$s$-slice is pointwise $1+O(n^{-c})$ close to its stationary reference.
Jensen's inequality, averaged over the random $j$-set, therefore gives
\begin{equation}\label{eq:shadow-R-compare}
 \|\mathsf R_s-\overline{\mathsf R}_s\|_{2\to2}\le n^{-c}.
\end{equation}
The operators in this comparison and in (B) are Markov
contractions for their respective measures, and the measures
are pointwise equivalent up to $1+O(n^{-c})$.
Their differences have bounded $L^\infty$ norm.
Interpolation thus gives, for each fixed $q>2$,
\begin{equation}\label{eq:shadow-product-perturb}
 \|\mathsf R_s\mathsf D\mathsf U-\overline{\mathsf R}_s\,\overline{\mathsf D\mathsf U}\|_{q\to q}
 \le\varepsilon,\qquad \varepsilon=n^{-c_{F,\eta,q}},
\end{equation}
where the norms may be taken under $\pi_s$ or uniform measure.
By (C), \eqref{eq:polynomial-perturb} with
$P(u)=(1+2u)^s$ gives, for every fixed $C$ and all large $n$,
\begin{equation}\label{eq:perturbation-semigroup-bound}
 \|e^{-u\mathsf R_s\mathsf D\mathsf U}\|_{q\to q}
 \le2(1+2u)^s\qquad(0\le u\le C\log D_\star).
\end{equation}
Apply \eqref{eq:ABBA-identity} with
$A=\mathsf U$ and $B=\mathsf R_s\mathsf D$.
By \eqref{eq:resource-factorisation}, contraction of $A,B$,
and the preceding bound,
\begin{equation}\label{eq:ab-ba-reduction}
 \|e^{-u\mathsf T_0}\|_{q\to q}
 \le1+\int_0^u\|e^{-v\mathsf R_s\mathsf D\mathsf U}\|_{q\to q}\,dv
 \le C_F(1+u)^{s+1}.
\end{equation}
Finally, (A), interpolation and \eqref{eq:polynomial-perturb}
transfer this bound to $e^{-u\mathsf T}$ throughout
$u=O(\log D_\star)$.  Taking $u=(r-1)t$ proves
\eqref{eq:resource-semigroup-goal}.

\label{lem:role-counts}
Uniformly over $e$, $j$ with $\lambda_j>0$, and $J\in\binom ej$,
\begin{equation}\label{eq:role-counting}
 s_J(e)=(1+O(n^{-c}))
 \frac{(r-1)\lambda_j}{\binom kj}\,d_e.
\end{equation}

\label{lem:shadow-fibre}
Uniformly over feasible $\ell<s$ and $\ell$-sets $J$,
\[
 \|\mathsf L_J^{(\ell)}-\Pi_J^{(s)}\|_{L^2(\nu_J)\to L^2(\nu_J)}
 \le n^{-c}.
\]

\label{lem:one-ended-balance}
For a role edge $f\in E(F)$ and $f\subseteq U\subseteq V(F)$,
\begin{equation}\label{eq:original-template-balance}
 e(F[U])-1\le\rho(|U|-k).
\end{equation}
The inequality is strict when $U\ne V(F)$ and $F[U]$
contains another edge.  Consequently, for any $F$-chain $C$
rooted at $e_0$ and $U\supseteq e_0$,
\begin{equation}\label{eq:persistent-chain-balance}
 e(C[U])-1\le\rho(|U|-k).
\end{equation}
The latter inequality also holds for the reversed chain.

\label{lem:shadow-chain-balance}
For every feasible $\ell<s$ and $L\ge2$, the template
\eqref{eq:shadow-chain-definition} is strictly balanced when
rooted at $I$.  Every proper rooted subtemplate with at least
one tested edge has density at most $1/(k-s)$, whereas the
full rooted density is
\begin{equation}\label{eq:shadow-chain-strict-balance}
 \frac{L}{L(k-s)-(s-\ell)}>\frac1{k-s}.
\end{equation}

\label{thm:cyclic-sparsity}
For each fixed integer $R\ge4$ there are constants
$C_{F,R}<\infty$ and $\eta_{F,R}>0$ such that, if
$0<\eta<\eta_{F,R}$, then uniformly on $\mathcal G_\star$,
\begin{equation}\label{eq:short-cycle-target}
 \chi_R(\Gamma_\star)
 \le n^{-1/b+C_{F,R}\eta}.
\end{equation}

\label{prop:JK-handoff}
Fix $F$ and sufficiently small $\eta>0$.  For every sufficiently small
$\delta_{\rm JK}>0$ depending only on $F,\eta$, there is an event
$\mathcal G_\star$ with
\[
 \mathbb P(\mathcal G_\star^c)
 \le\exp\{-(\log n)^{4/3}\}
\]
such that the following hold simultaneously for \emph{all} rooted
$k$-templates of order at most $\eta^{-4}$ satisfying the hypotheses
in the respective parts, and for \emph{all} admissible prescribed root
injections.  In parts (iii) and (iv), $C_{A,I}$ and $C_{A,J}$ denote
fixed template-dependent exponents.

\begin{enumerate}[label=\textup{(\roman*)}]
\item For every role edge $f\in E(F)$, every resource
$e\in E(H_\star)$, and every bijection $\sigma:f\to e$,
\begin{equation}\label{eq:rooted-F-count}
 \Phi_{F,\sigma}
 =\left(1+n^{-\Omega_{F,\eta}(1)}\right)n^ap_\star^b.
\end{equation}

\item Let $(A,I)$ be a balanced template with
$|V(A)|\le\eta^{-4}$.  If
\(
 i^\star<i_{A,I}^{\delta_{\rm JK}^{1/2}},
\)
then for all root embeddings $\psi$ we have
\begin{equation}\label{eq:JK-balanced-count}
 \Phi_{A,\psi}
 =\left(1+O(\zeta(i^\star)^{\delta_{\rm JK}})\right)
 \widehat\phi_{A,I}(i^\star).
\end{equation}

\item For every strictly balanced template $(A,I)$ with
$|V(A)|\le\eta^{-4}$ we have
\[
 \Phi_{A,\psi}
 \le(1+\log n)^{C_{A,I}}
 \max\{1,\widehat\phi_{A,I}(i^\star)\}.
\]

\item Let $I\subsetneq J\subseteq V(A)$ and
$|V(A)|\le\eta^{-4}$.  Among subtemplates $(B,I)\subseteq(A,I)$ whose vertex
set contains $J$, choose one minimising $\widehat\phi_{B,I}(i^\star)$.  Then
for all injections $\psi:J\hookrightarrow V(H_\star)$ we have
\begin{equation}\label{eq:JK-enlarged-root-count}
 \Phi_{A,\psi}
 \le(1+\log n)^{C_{A,J}}
 \frac{\widehat\phi_{A,I}(i^\star)}
 {\widehat\phi_{B,I}(i^\star)}.
\end{equation}
\end{enumerate}
